public final class PairingSessionMock: PairingSession, @unchecked Sendable {
    public init() { }


    private let startState = MockoloMutex(MockoloHandlerState<Never, @Sendable () async throws -> ()>())
    public var startCallCount: Int {
        return startState.withLock(\.callCount)
    }
    public var startHandler: (@Sendable () async throws -> ())? {
        get { startState.withLock(\.handler) }
        set { startState.withLock { $0.handler = newValue } }
    }
    public func start() async throws {
        let startHandler = startState.withLock { state in
            state.callCount += 1
            return state.handler
        }
        if let startHandler = startHandler {
            try await startHandler()
        }

    }

    private let confirmState = MockoloMutex(MockoloHandlerState<String, @Sendable (String) async throws -> ConnectionData>())
    public var confirmCallCount: Int {
        return confirmState.withLock(\.callCount)
    }
    public var confirmArgValues: [String] {
        return confirmState.withLock(\.argValues).map(\.value)
    }
    public var confirmHandler: (@Sendable (String) async throws -> ConnectionData)? {
        get { confirmState.withLock(\.handler) }
        set { confirmState.withLock { $0.handler = newValue } }
    }
    public func confirm(pin: String) async throws -> ConnectionData {
        warnIfNotSendable(pin)
        let confirmHandler = confirmState.withLock { state in
            state.callCount += 1
            state.argValues.append(.init((pin)))
            return state.handler
        }
        if let confirmHandler = confirmHandler {
            return try await confirmHandler(pin)
        }
        fatalError("confirmHandler returns can't have a default value thus its handler must be set")
    }

    private let cancelState = MockoloMutex(MockoloHandlerState<Never, @Sendable () async -> ()>())
    public var cancelCallCount: Int {
        return cancelState.withLock(\.callCount)
    }
    public var cancelHandler: (@Sendable () async -> ())? {
        get { cancelState.withLock(\.handler) }
        set { cancelState.withLock { $0.handler = newValue } }
    }
    public func cancel() async {
        let cancelHandler = cancelState.withLock { state in
            state.callCount += 1
            return state.handler
        }
        if let cancelHandler = cancelHandler {
            await cancelHandler()
        }

    }
}

fileprivate func warnIfNotSendable<each T>(function: String = #function, _: repeat each T) {
    print("At \(function), the captured arguments are not Sendable, it is not concurrency-safe.")
}

fileprivate func warnIfNotSendable<each T: Sendable>(function: String = #function, _: repeat each T) {
}

/// Will be replaced to `Synchronization.Mutex` in future.
fileprivate final class MockoloMutex<Value>: @unchecked Sendable {
    private let lock = NSLock()
    private var value: Value
    init(_ initialValue: Value) {
        self.value = initialValue
    }
#if compiler(>=6.0)
    borrowing func withLock<Result, E: Error>(_ body: (inout sending Value) throws(E) -> Result) throws(E) -> sending Result {
        lock.lock()
        defer { lock.unlock() }
        return try body(&value)
    }
#else
    func withLock<Result>(_ body: (inout Value) throws -> Result) rethrows -> Result {
        lock.lock()
        defer { lock.unlock() }
        return try body(&value)
    }
#endif
}

fileprivate struct MockoloUnsafeTransfer<Value>: @unchecked Sendable {
    var value: Value
    init(_ value: Value) {
        self.value = value
    }
}

fileprivate struct MockoloHandlerState<Arg, Handler> {
    var argValues: [MockoloUnsafeTransfer<Arg>] = []
    var handler: Handler? = nil
    var callCount: Int = 0
}
